-- Generated by validator.py from the configuration workbook.
-- dialect: postgres, id_type: integer. Do not edit by hand; change the config and regenerate.

-- Registry of ingested files. Loading the same file twice creates a new
-- file_id, so every staged row stays attributable to one physical load.
CREATE TABLE swiggy_source_file (
    file_id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    file_name        TEXT NOT NULL,
    file_sha256      TEXT NOT NULL,
    row_count        INTEGER,
    loaded_at        TIMESTAMP NOT NULL
);
CREATE UNIQUE INDEX ux_swiggy_source_file_hash ON swiggy_source_file (file_sha256);

-- Snapshot of the configuration that produced the tables below.
CREATE TABLE swiggy_load_config_audit (
    config_id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    file_id          BIGINT NOT NULL REFERENCES swiggy_source_file (file_id),
    table_name       TEXT NOT NULL,
    sheet_name       TEXT NOT NULL,
    header_row       INTEGER,
    data_start_row   INTEGER,
    data_end_row     INTEGER,
    column_count     INTEGER,
    loaded_at        TIMESTAMP NOT NULL
);

-- Summary!row 12+ - Payout header: label in col B, value in col C
CREATE TABLE swiggy_summary (
    summary_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    file_id BIGINT NOT NULL REFERENCES swiggy_source_file (file_id),
    sheet_name TEXT NOT NULL,
    source_row_num INTEGER NOT NULL,
    field_label TEXT NOT NULL,
    field_value TEXT NOT NULL
);
CREATE UNIQUE INDEX ux_swiggy_summary_row ON swiggy_summary (file_id, sheet_name, source_row_num);
CREATE INDEX ix_swiggy_summary_file ON swiggy_summary (file_id);
CREATE INDEX ix_swiggy_summary_key ON swiggy_summary (field_label);

