    swiggy_delivered NUMERIC(18,4),
    swiggy_cancelled NUMERIC(18,4),
    toing_delivered NUMERIC(18,4),
    toing_cancelled NUMERIC(18,4),
    total_amount NUMERIC(18,4)
);
CREATE UNIQUE INDEX ux_swiggy_payout_breakup_row ON swiggy_payout_breakup (file_id, sheet_name, source_row_num);
CREATE INDEX ix_swiggy_payout_breakup_file ON swiggy_payout_breakup (file_id);

